189	    @ResponseBody
190	    public ResponseEntity<ProblemDetail> handleMissingOwnerFieldsException(MissingOwnerFieldsException e, HttpServletRequest request) {
191	        HttpStatus status = HttpStatus.BAD_REQUEST;
192	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
193	        detail.setProperty("errors", e.getFields());
194	        return ResponseEntity.status(status).body(detail);
195	    }
196	
197	    /**
198	     * Handles {@link InvalidTelephoneException} raised when a submitted telephone number cannot be
199	     * converted to a valid E.164 value, returning a 400 Bad Request.
200	     *
201	     * @param e The {@link InvalidTelephoneException} to be handled
202	     * @param request {@link HttpServletRequest} object referring to the current request.
203	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
204	     */
205	    @ExceptionHandler(InvalidTelephoneException.class)
206	    @ResponseBody
207	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
208	        HttpStatus status = HttpStatus.BAD_REQUEST;
209	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
210	        detail.setProperty("errors", List.of("telephone"));
211	        return ResponseEntity.status(status).body(detail);
212	    }
213	
214	    /**
215	     * Handles {@link DuplicateIdentityException} raised when a new owner's identity key (normalized
216	     * telephone, email and household id) exactly matches that of an existing owner, returning a 409
217	     * Conflict.
218	     *
219	     * @param e The {@link DuplicateIdentityException} to be handled
220	     * @param request {@link HttpServletRequest} object referring to the current request.
221	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
222	     */
223	    @ExceptionHandler(DuplicateIdentityException.class)
224	    @ResponseBody
225	    public ResponseEntity<ProblemDetail> handleDuplicateIdentityException(DuplicateIdentityException e, HttpServletRequest request) {
226	        HttpStatus status = HttpStatus.CONFLICT;
227	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_IDENTITY);
228	        detail.setProperty("errors", List.of("identityKey"));
229	        return ResponseEntity.status(status).body(detail);
230	    }
231	
232	    /**
233	     * Handles {@link CityCapacityExceededException} raised when a new owner is submitted for a city
234	     * that already holds the maximum number of owners, returning a 409 Conflict.
235	     *
236	     * @param e The {@link CityCapacityExceededException} to be handled
