242	    public ResponseEntity<ProblemDetail> handleCityCapacityExceededException(CityCapacityExceededException e, HttpServletRequest request) {
243	        HttpStatus status = HttpStatus.CONFLICT;
244	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_CITY_AT_CAPACITY);
245	        detail.setProperty("errors", List.of("city"));
246	        return ResponseEntity.status(status).body(detail);
247	    }
