249	    /**
250	     * Handles {@link DailyOwnerLimitExceededException} raised when the maximum number of owners
251	     * allowed to be registered on a single day has already been reached, returning a 429 Too Many
252	     * Requests.
253	     *
254	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
255	     * @param request {@link HttpServletRequest} object referring to the current request.
256	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
257	     */
258	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
